namespace SharpImage.Tests.Formats;

// Animated AVIF (image sequences, 'avis'): HeifCoder.DecodeSequence against libavif 1.4.2 (avifdec --index i) on its own
// test files (tests/data, BSD) and a libavif-encoded 4:4:4 sequence with an alpha track. Pixels are sampled from every
// frame; timing (media timescale, per-sample durations) and the loop count follow libavif's track parsing (repetition
// count from the edit list: none = unknown -> 0 = loop forever, flags 0 = play once, else repetitions + 1).
