    public async Task FramesAndTimingMatchLibavif(string file, int bd, int w, int h, long timescale, int loops,
        string durations, string refs)
    {
        byte[] data = File.ReadAllBytes(Asset(file));
        using var seq = HeifCoder.DecodeSequence(data);
        string[] perFrame = refs.Split('|');
        await Assert.That(seq.Count).IsEqualTo(perFrame.Length);
        await Assert.That(seq.Timescale).IsEqualTo(timescale);
        await Assert.That(seq.LoopCount).IsEqualTo(loops);
        await Assert.That(string.Join(",", seq.Frames.Select(f => f.DurationTicks))).IsEqualTo(durations);
        int max = (1 << bd) - 1, worst = 0;
        for (int i = 0; i < seq.Count; i++)
        {
            var img = seq[i];
            await Assert.That((int)img.Columns).IsEqualTo(w);
            await Assert.That((int)img.Rows).IsEqualTo(h);
            int ch = img.NumberOfChannels;
            foreach (var m in System.Text.RegularExpressions.Regex.Matches(perFrame[i], @"\((\d+),(\d+),(\d+),(\d+),(\d+),(\d+)\)"))
            {
                var g = ((System.Text.RegularExpressions.Match)m).Groups;
                int y = int.Parse(g[1].Value), x = int.Parse(g[2].Value);
                var row = img.GetPixelRow(y);
                for (int c = 0; c < 4; c++)
                {
                    int v16 = c < 3 ? row[x * ch + c] : img.HasAlpha ? row[x * ch + ch - 1] : 65535;
                    int ours = (int)Math.Round(v16 * (double)max / 65535.0);
                    worst = Math.Max(worst, Math.Abs(ours - int.Parse(g[3 + c].Value)));
                }
            }
        }
        await Assert.That(worst).IsEqualTo(0);

        // libavif's AUTO source: an 'avis' file decodes as its sequence, so the single-image decode is frame 0.
        var first = HeifCoder.Decode(data);
        await Assert.That(first.GetPixelRow(h / 2).ToArray()).IsEquivalentTo(seq[0].GetPixelRow(h / 2).ToArray());
    }

    [Test]
    public async Task StillAvifDecodesAsOneFrameSequence()
    {
        byte[] data = File.ReadAllBytes(Asset("sharpimage_8bit_420_161x97_alpha.avif"));
        using var seq = HeifCoder.DecodeSequence(data);
        await Assert.That(seq.Count).IsEqualTo(1);
        await Assert.That((int)seq[0].Columns).IsEqualTo(161);
    }
